#!/usr/bin/env bash
# UC7 — Margin Guardian: the OMS tells you where money is leaking this week and hands you the prompt to fix it
# (section 13 KPIs, GR-17 AI cost, FR-MON-08 / FR-ANL-04). Facts are computed deterministically from the ledger; the
# LLM only writes the narrative, and every number is checked against the facts.
source "$(dirname "$0")/lib.sh"
hr; echo "UC7 · Margin Guardian — the weekly digest with a prompt per finding"; hr
step "1) Ask the OMS a question in plain English (whitelisted, parameterised queries — the SQL is shown)"
for Q in "How many orders are released right now and at which nodes?" "Which open orders are at risk of missing their promise?" "What is the split-shipment rate by channel this week?"; do
  echo "    Q: $Q"
  api POST /api/v1/copilot/ops/ask "$(Q_TEXT="$Q" python3 -c 'import json,os; print(json.dumps({"question": os.environ["Q_TEXT"]}))')" | jq_ 'print("    A:", (d.get("answer") or "")[:300]); print("       query", d.get("queryName"), d.get("parameters"), "| rows", d.get("rowCount")); print("       sql:", " ".join((d.get("sql") or "").split())[:160])'
done
step "2) Run the digest over the last 7 days"
api POST "/api/v1/copilot/digest/run?days=7" | jq_ '
print("    headline:", d.get("headline"))
for f in d.get("findings") or []:
    print("    ·", f.get("title")); print("       ", f.get("metric"), "=", f.get("value"), ("Δ "+str(f.get("delta"))) if f.get("delta") else ""); print("        evidence:", (f.get("evidence") or "")[:200]); print("        → prompt:", (f.get("suggestedPrompt") or "")[:160])
fx=d.get("facts") or {}; print("    facts: orders", fx.get("orders"), "| split", (fx.get("splits") or {}).get("split_rate_pct"), "% | below floor", (fx.get("belowFloor") or {}).get("below_floor_orders"), "| AI $", (fx.get("aiCost") or {}).get("total_usd"))
print("    generated by", d.get("model") if d.get("generated") else "deterministic fallback")'
step "3) Explain a decision to a customer in plain language (customer-safe, generated and labelled)"
REC=$(api GET "/api/v1/decision-records?subjectType=order&subjectId=$(api GET '/api/v1/orders?limit=1' | j 'd["items"][0]["id"]')" | j 'next((r["id"] for r in d if r.get("decision") in ("fulfilment_intent","sourcing_node_score")), d[0]["id"] if d else "")')
[ -n "$REC" ] && api GET "/api/v1/copilot/explain/$REC?audience=customer" | jq_ 'print("    "+(d.get("text") or "")[:400]); print("    generated:", d.get("generated"), "| model:", d.get("model"))'
step "4) Draft a CS reply grounded only in order facts"
OID=$(api GET '/api/v1/orders?status=shipped,delivered&limit=1' | j 'd["items"][0]["id"] if d.get("items") else ""')
[ -n "$OID" ] && api POST /api/v1/copilot/cs/draft "{\"orderId\":\"$OID\",\"message\":\"Hi, where is my order? I need it before the weekend, can you check?\"}" | jq_ 'print("    intent:", (d.get("intent") or {}).get("intent"), "| confidence", round(((d.get("intent") or {}).get("confidence") or 0),2)); print("    draft:", (d.get("draft") or "")[:400]); print("    facts used:", d.get("factsUsed")); print("    slots:", d.get("slots"))'
echo; say "Open $BASE/analytics (Margin Guardian) and $BASE/control-tower (Ask the OMS). Talk track: the system computes the money, the model writes the sentence, every number is checked, and each finding is one click from a governed change."
